  // keep the evens first, then transform what survived
}

challenge-set.solution:
function evenSquares(xs) {
  return xs.filter((n) => n % 2 === 0).map((n) => n * n);
}

challenge-set.starterCode:
function longestWord(words) {
  // reduce carries the best answer so far as the accumulator
  // what should that accumulator start as?
}

challenge-set.solution:
function longestWord(words) {
  return words.reduce((best, w) => {
    if (w.length > best.length) {
      return w;
    }
    return best;
  }, "");
}

