function nextInLine(queue) {
  // one call takes from the front, another puts it on the back
  return queue;
}

exam.solution:
function nextInLine(queue) {
  if (queue.length === 0) {
    return queue;
  }
  queue.push(queue.shift());
  return queue;
}
